import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, useInView } from 'framer-motion';
import { Button } from '../ui/button';
import { Download, Github, Linkedin, Mail, ArrowDown } from 'lucide-react';

export default function HeroSection() {
    const [currentTitleIndex, setCurrentTitleIndex] = useState(0);
    const titles = [
        'Process Engineer · Flex & Rigid PCB Manufacturing',
        'Factory Automation & Production Data Systems',
        'SMT Process Optimization · AS9100',
        'Building Depth in Signal & Power Integrity'
    ];

    // Detect when hero section enters viewport
    const sectionRef = useRef(null);
    const isInView = useInView(sectionRef, { once: false, amount: 0.1 });

    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentTitleIndex((prevIndex) => (prevIndex + 1) % titles.length);
        }, 3000);
        return () => clearInterval(interval);
    }, [titles.length]);

    const handleDownloadResume = () => {
        const link = document.createElement('a');
        link.href =
            'Abdullah_Syed_Resume_2026.pdf';
        link.download = 'Abdullah_Syed_Resume.pdf';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    // Animation variants reused across motion divs
    const fadeUp = (delay = 0) => ({
        hidden: { opacity: 0, y: 30 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.8, delay },
        },
    });

    return (
        <section
            ref={sectionRef}
            className="min-h-screen flex items-center justify-center bg-background"
        >
            <div className="max-w-7xl mx-auto px-6 sm:px-8 py-20">
                <div className="text-center">
                    <motion.div
                        variants={fadeUp(0)}
                        initial="hidden"
                        animate={isInView ? 'visible' : 'hidden'}
                    >
                        <h1 className="text-5xl md:text-7xl font-bold text-foreground mb-6">
                            <span className="bg-gradient-to-r from-blue-500 via-purple-500 to-indigo-600 bg-clip-text text-transparent">
                                Hey there! I'm Abdullah Syed
                            </span>
                        </h1>
                        <div className="text-xl md:text-2xl text-foreground/80 dark:text-slate-300 mb-8 font-light h-8">
                            <AnimatePresence mode="wait">
                                <motion.span
                                    key={currentTitleIndex}
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    exit={{ opacity: 0, y: -20 }}
                                    transition={{ duration: 0.5 }}
                                >
                                    {titles[currentTitleIndex]}
                                </motion.span>
                            </AnimatePresence>
                        </div>
                    </motion.div>

                    <motion.div
                        variants={fadeUp(0.2)}
                        initial="hidden"
                        animate={isInView ? 'visible' : 'hidden'}
                        className="max-w-3xl mx-auto mb-12"
                    >
                        <p className="text-lg text-foreground/70 dark:text-slate-400 leading-relaxed">
                            Process engineer in flex and rigid-flex PCB manufacturing — building the factory data systems and automation behind real improvements in yield and fallout.
                            Deepening into signal integrity and controlled-impedance design, where production-floor experience meets high-speed board engineering.
                        </p>

                    </motion.div>

                    <motion.div
                        variants={fadeUp(0.4)}
                        initial="hidden"
                        animate={isInView ? 'visible' : 'hidden'}
                        className="flex flex-wrap justify-center gap-4 mb-16"
                    >
                        <Button
                            onClick={handleDownloadResume}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 text-lg flex items-center justify-center"
                        >
                            <Download className="w-5 h-5 mr-2" />
                            Download Resume
                        </Button>

                        <Button
                            variant="outline"
                            className="px-8 py-3 text-lg border-slate-400 dark:border-slate-600 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 flex items-center justify-center"
                            onClick={() =>
                                window.open('https://www.linkedin.com/in/abdullah-syed-aaa302280/', '_blank')
                            }
                        >
                            <Linkedin className="w-5 h-5 mr-2" />
                            LinkedIn
                        </Button>

                        <Button
                            variant="outline"
                            className="px-8 py-3 text-lg border-slate-400 dark:border-slate-600 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 flex items-center justify-center"
                            onClick={() =>
                                window.open('https://github.com/Abdullah-Ali-Syed', '_blank')
                            }
                        >
                            <Github className="w-5 h-5 mr-2" />
                            GitHub
                        </Button>

                        <Button
                            variant="outline"
                            className="px-8 py-3 text-lg border-slate-400 dark:border-slate-600 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 flex items-center justify-center"
                            onClick={() =>
                                document.getElementById('contact').scrollIntoView({ behavior: 'smooth' })
                            }
                        >
                            <Mail className="w-5 h-5 mr-2" />
                            Contact
                        </Button>

                    </motion.div>

                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: isInView ? 1 : 0 }}
                        transition={{ duration: 1, delay: 0.8 }}
                        className="animate-bounce"
                    >
                        <ArrowDown
                            className="w-6 h-6 text-foreground/40 mx-auto cursor-pointer hover:text-blue-500 transition-colors"
                            onClick={() =>
                                document
                                    .getElementById('about')
                                    .scrollIntoView({ behavior: 'smooth' })
                            }
                        />
                    </motion.div>
                </div>
            </div>
        </section>
    );
}
