import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ExternalLink, Github, Star, X, Maximize2, CheckCircle2 } from 'lucide-react';
import Project from '../../entities/Project.js';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';

export default function ProjectsSection() {
    const [featuredProject, setFeaturedProject] = useState(null);
    const [otherProjects, setOtherProjects] = useState([]);
    const [selectedProject, setSelectedProject] = useState(null);
    const [imageExpanded, setImageExpanded] = useState(false);

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        const allProjects = await Project.list('-created_date');
        const featured = allProjects.find((p) => p.is_featured) || allProjects[0];
        const others = allProjects.filter((p) => p.id !== featured.id);
        setFeaturedProject(featured);
        setOtherProjects(others);
    };

    const openDetails = (project) => {
        setSelectedProject(project);
        setImageExpanded(false);
    };

    const closeDetails = useCallback(() => {
        setSelectedProject(null);
        setImageExpanded(false);
    }, []);

    // Close on Escape + lock body scroll while modal is open
    useEffect(() => {
        if (!selectedProject) return;
        const onKey = (e) => e.key === 'Escape' && closeDetails();
        window.addEventListener('keydown', onKey);
        document.body.style.overflow = 'hidden';
        return () => {
            window.removeEventListener('keydown', onKey);
            document.body.style.overflow = '';
        };
    }, [selectedProject, closeDetails]);

    // Card media: opens the modal for internal projects (details), external link otherwise
    const CardMedia = ({ project, tall }) => {
        const inner = (
            <motion.div
                className={
                    tall
                        ? 'bg-muted rounded-xl p-8 flex items-center justify-center min-h-[300px] overflow-hidden cursor-pointer'
                        : 'h-48 bg-gradient-to-br from-blue-500/20 to-purple-600/20 flex items-center justify-center overflow-hidden cursor-pointer'
                }
                whileHover={{ scale: 1.05 }}
                transition={{ type: 'spring', stiffness: 300, damping: 20 }}
            >
                <img
                    src={process.env.PUBLIC_URL + project.image_url}
                    alt={project.title}
                    style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain', display: 'block' }}
                />
            </motion.div>
        );
        if (project.details) {
            return (
                <button type="button" onClick={() => openDetails(project)} className="block w-full text-left">
                    {inner}
                </button>
            );
        }
        return (
            <a href={project.demo_url} target="_blank" rel="noopener noreferrer" className="block">
                {inner}
            </a>
        );
    };

    return (
        <section id="projects" className="py-20 bg-background">
            <div className="max-w-7xl mx-auto px-6 sm:px-8">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.8, ease: 'easeOut' }}
                    viewport={{ once: false, amount: 0.1 }}
                    className="text-center mb-16"
                >
                    <h2 className="text-4xl md:text-5xl font-bold text-foreground mb-6">
                        Featured{' '}
                        <span className="bg-gradient-to-r from-blue-500 to-purple-600 bg-clip-text text-transparent">
                            Projects
                        </span>
                    </h2>
                    <div className="w-24 h-1 bg-gradient-to-r from-blue-500 to-purple-600 mx-auto rounded-full"></div>
                    <p className="text-foreground/70 mt-6 text-lg max-w-2xl mx-auto">
                        Production systems I've architected on the factory floor, alongside the
                        hardware and signal-chain projects steering my work toward signal integrity
                    </p>
                </motion.div>

                {/* Featured Project Banner */}
                {featuredProject && (
                    <motion.div
                        initial={{ opacity: 0, y: 30 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.8, ease: 'easeOut' }}
                        viewport={{ once: false, amount: 0.1 }}
                        className="bg-gradient-to-r from-blue-500/10 to-purple-600/10 rounded-2xl p-8 mb-16 border border-blue-200 dark:border-blue-800"
                    >
                        <div className="grid lg:grid-cols-2 gap-8 items-center">
                            <div>
                                <div className="flex items-center gap-2 mb-4">
                                    <Star className="w-5 h-5 text-yellow-500 fill-current" />
                                    <span className="text-sm font-medium text-blue-600 dark:text-blue-400">
                                        Featured Project
                                    </span>
                                </div>
                                <h3 className="text-3xl font-bold text-foreground mb-4">
                                    {featuredProject.title}
                                </h3>
                                <p className="text-foreground/80 text-lg leading-relaxed mb-6">
                                    {featuredProject.description}
                                </p>
                                <div className="flex flex-wrap gap-2 mb-6">
                                    {featuredProject.technologies?.map((tech, index) => (
                                        <Badge key={index} variant="secondary" className="text-sm">
                                            {tech}
                                        </Badge>
                                    ))}
                                </div>
                                <div className="flex gap-4">
                                    {featuredProject.details && (
                                        <Button onClick={() => openDetails(featuredProject)}>
                                            <Maximize2 className="w-4 h-4 mr-2" />
                                            View Details
                                        </Button>
                                    )}
                                    {featuredProject.github_url && (
                                        <Button
                                            variant="outline"
                                            onClick={() => window.open(featuredProject.github_url, '_blank')}
                                        >
                                            <Github className="w-4 h-4 mr-2" />
                                            Info
                                        </Button>
                                    )}
                                    {featuredProject.demo_url && (
                                        <Button onClick={() => window.open(featuredProject.demo_url, '_blank')}>
                                            <ExternalLink className="w-4 h-4 mr-2" />
                                            Live Demo
                                        </Button>
                                    )}
                                </div>
                            </div>
                            <CardMedia project={featuredProject} tall />
                        </div>
                    </motion.div>
                )}

                {/* Project Grid */}
                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {otherProjects.map((project, index) => (
                        <motion.div
                            key={project.id}
                            initial={{ opacity: 0, y: 30 }}
                            whileInView={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.6, delay: index * 0.1, ease: 'easeOut' }}
                            viewport={{ once: false, amount: 0.1 }}
                            className="bg-muted rounded-xl overflow-hidden shadow-lg hover:shadow-xl transition-all duration-300 border border-border"
                        >
                            <CardMedia project={project} />

                            <div className="p-6">
                                <h3 className="text-xl font-semibold text-foreground mb-3">
                                    {project.title}
                                </h3>
                                <p className="text-foreground/70 mb-4 text-sm leading-relaxed">
                                    {project.description}
                                </p>

                                {project.technologies && (
                                    <div className="flex flex-wrap gap-2 mb-4">
                                        {project.technologies.slice(0, 3).map((tech, techIndex) => (
                                            <Badge key={techIndex} variant="outline" className="text-xs">
                                                {tech}
                                            </Badge>
                                        ))}
                                        {project.technologies.length > 3 && (
                                            <Badge variant="outline" className="text-xs">
                                                +{project.technologies.length - 3}
                                            </Badge>
                                        )}
                                    </div>
                                )}

                                <div className="flex gap-2">
                                    {project.details && (
                                        <Button size="sm" onClick={() => openDetails(project)}>
                                            <Maximize2 className="w-3 h-3 mr-1" />
                                            Details
                                        </Button>
                                    )}
                                    {project.github_url && (
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            onClick={() => window.open(project.github_url, '_blank')}
                                        >
                                            <Github className="w-3 h-3 mr-1" />
                                            Code
                                        </Button>
                                    )}
                                    {project.demo_url && (
                                        <Button size="sm" onClick={() => window.open(project.demo_url, '_blank')}>
                                            <ExternalLink className="w-3 h-3 mr-1" />
                                            Demo
                                        </Button>
                                    )}
                                </div>
                            </div>
                        </motion.div>
                    ))}
                </div>
            </div>

            {/* ======= Project Detail Modal ======= */}
            <AnimatePresence>
                {selectedProject && selectedProject.details && (
                    <motion.div
                        className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-8"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                    >
                        {/* Backdrop */}
                        <div
                            className="absolute inset-0 bg-black/60 backdrop-blur-sm"
                            onClick={closeDetails}
                        />

                        {/* Panel */}
                        <motion.div
                            className="relative bg-background border border-border rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-y-auto"
                            initial={{ opacity: 0, scale: 0.94, y: 24 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.96, y: 16 }}
                            transition={{ type: 'spring', stiffness: 260, damping: 24 }}
                            role="dialog"
                            aria-modal="true"
                            aria-label={selectedProject.title}
                        >
                            {/* Close */}
                            <button
                                type="button"
                                onClick={closeDetails}
                                aria-label="Close details"
                                className="absolute top-4 right-4 z-10 rounded-full bg-background/80 backdrop-blur border border-border p-2 text-foreground/70 hover:text-foreground hover:bg-muted transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>

                            {/* Expandable diagram */}
                            <div
                                className={`bg-gradient-to-br from-blue-500/10 to-purple-600/10 border-b border-border flex items-center justify-center cursor-zoom-in transition-all duration-300 ${
                                    imageExpanded ? 'p-2' : 'p-6 max-h-[45vh]'
                                }`}
                                onClick={() => setImageExpanded((v) => !v)}
                                title={imageExpanded ? 'Click to shrink' : 'Click to expand'}
                            >
                                <img
                                    src={process.env.PUBLIC_URL + selectedProject.image_url}
                                    alt={`${selectedProject.title} — architecture diagram`}
                                    style={{
                                        maxWidth: '100%',
                                        maxHeight: imageExpanded ? 'none' : '40vh',
                                        objectFit: 'contain',
                                        display: 'block',
                                    }}
                                />
                            </div>

                            <div className="p-6 sm:p-8">
                                <h3 className="text-2xl sm:text-3xl font-bold text-foreground mb-1">
                                    {selectedProject.title}
                                </h3>
                                <p className="text-sm font-medium bg-gradient-to-r from-blue-500 to-purple-600 bg-clip-text text-transparent mb-6">
                                    {selectedProject.details.role}
                                </p>

                                {selectedProject.details.paragraphs?.map((para, i) => (
                                    <p key={i} className="text-foreground/80 leading-relaxed mb-4">
                                        {para}
                                    </p>
                                ))}

                                {selectedProject.details.highlights && (
                                    <div className="bg-muted rounded-xl border border-border p-5 my-6">
                                        <p className="text-sm font-semibold text-foreground mb-3">
                                            Key outcomes
                                        </p>
                                        <ul className="space-y-2">
                                            {selectedProject.details.highlights.map((h, i) => (
                                                <li key={i} className="flex items-start gap-2 text-sm text-foreground/80">
                                                    <CheckCircle2 className="w-4 h-4 mt-0.5 shrink-0 text-blue-500" />
                                                    <span>{h}</span>
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                )}

                                <div className="flex flex-wrap gap-2 mb-6">
                                    {selectedProject.technologies?.map((tech, i) => (
                                        <Badge key={i} variant="secondary" className="text-xs">
                                            {tech}
                                        </Badge>
                                    ))}
                                </div>

                                {selectedProject.details.note && (
                                    <p className="text-xs italic text-foreground/50 border-t border-border pt-4">
                                        {selectedProject.details.note}
                                    </p>
                                )}
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </section>
    );
}
