import React, { useState, useEffect } from "react";
import { Link as RouterLink } from "react-router-dom";
import { Link as ScrollLink, animateScroll as scroll } from "react-scroll";
import { Menu, X, Sun, Moon, Download } from "lucide-react";
import { Button } from "../components/ui/button";
import { motion, AnimatePresence } from 'framer-motion';

export default function Layout({ children }) {
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [isDarkMode, setIsDarkMode] = useState(false);
    const [showStickyButton, setShowStickyButton] = useState(false);

    useEffect(() => {
        const savedTheme = localStorage.getItem('theme');
        const systemDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        setIsDarkMode(savedTheme === 'dark' || (!savedTheme && systemDark));
    }, []);

    useEffect(() => {
        if (isDarkMode) {
            document.documentElement.classList.add('dark');
            localStorage.setItem('theme', 'dark');
        } else {
            document.documentElement.classList.remove('dark');
            localStorage.setItem('theme', 'light');
        }
    }, [isDarkMode]);

    useEffect(() => {
        const handleScroll = () => {
            if (window.scrollY > window.innerHeight * 0.8) {
                setShowStickyButton(true);
            } else {
                setShowStickyButton(false);
            }
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const toggleTheme = () => {
        setIsDarkMode(!isDarkMode);
    };

    const handleDownloadResume = () => {
        const link = document.createElement('a');
        link.href =
            'Abdullah_Syed_Resume_2026.pdf';
        link.download = 'Abdullah_Syed_Resume.pdf';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const navigation = [
        { name: 'About', to: 'about' },
        { name: 'Experience', to: 'experience' },
        { name: 'Skills', to: 'skills' },
        { name: 'Projects', to: 'projects' },
        { name: 'Salience', to: 'venture', isBrand: true },
        { name: 'Community', to: 'community' },
        { name: 'Contact', to: 'contact' }
    ];

    return (
        <div className={`min-h-screen transition-colors duration-300 ${isDarkMode ? 'dark' : ''}`}>
            <style>{`
        :root {
          --primary: 59 130 246;
          --secondary: 99 102 241;
          --accent: 168 85 247;
          --background: 255 255 255;
          --foreground: 15 23 42;
          --muted: 248 250 252;
          --border: 226 232 240;
        }
        
        .dark {
          --background: 15 23 42;
          --foreground: 248 250 252;
          --muted: 30 41 59;
          --border: 51 65 85;
        }
        
        * {
          border-color: rgb(var(--border));
        }
        
        body {
          background-color: rgb(var(--background));
          color: rgb(var(--foreground));
        }
        
        .bg-background { background-color: rgb(var(--background)); }
        .bg-muted { background-color: rgb(var(--muted)); }
        .text-foreground { color: rgb(var(--foreground)); }
        .border-border { border-color: rgb(var(--border)); }
      `}</style>

            {/* Navigation */}
            <nav className="fixed top-0 w-full z-50 bg-background/80 backdrop-blur-md border-b border-border">
                <div className="max-w-7xl mx-auto px-6 sm:px-8">
                    <div className="flex justify-between items-center py-4">
                        {/* Logo */}
                        <RouterLink
                            to="/"
                            onClick={() => scroll.scrollToTop({ duration: 600 })}
                            className="text-2xl font-bold bg-gradient-to-r from-blue-500 to-purple-600 bg-clip-text text-transparent cursor-pointer"
                        >
                            Abdullah Syed
                        </RouterLink>

                        {/* Desktop Navigation */}
                        <div className="hidden md:flex items-center space-x-6">
                            {navigation.map((item) => (
                                <ScrollLink
                                    key={item.name}
                                    to={item.to}
                                    smooth={true}
                                    duration={600}
                                    offset={-80}
                                    className={
                                        item.isBrand
                                            ? "italic tracking-wide bg-gradient-to-r from-blue-500 to-purple-500 bg-clip-text text-transparent hover:from-blue-400 hover:to-purple-400 transition-all duration-200 font-semibold cursor-pointer"
                                            : "text-slate-700 dark:text-slate-300 hover:text-blue-500 dark:hover:text-blue-400 transition-colors duration-200 font-medium cursor-pointer"
                                    }
                                >
                                    {item.name}
                                </ScrollLink>
                            ))}
                            <AnimatePresence>
                                {showStickyButton && (
                                    <motion.div
                                        initial={{ opacity: 0, y: -10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        exit={{ opacity: 0, y: -10 }}
                                        transition={{ duration: 0.3 }}
                                    >
                                        <Button
                                            onClick={handleDownloadResume}
                                            size="sm"
                                            className="bg-blue-600 hover:bg-blue-700 text-white flex items-center justify-center"
                                        >
                                            <Download className="w-4 h-4 mr-2" />
                                            Resume
                                        </Button>

                                    </motion.div>
                                )}
                            </AnimatePresence>
                            <Button
                                variant="ghost"
                                size="icon"
                                onClick={toggleTheme}
                                className="ml-4"
                            >
                                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
                            </Button>
                        </div>

                        {/* Mobile menu button */}
                        <div className="md:hidden flex items-center space-x-2">
                            <Button variant="ghost" size="icon" onClick={toggleTheme}>
                                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
                            </Button>
                            <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => setIsMenuOpen(!isMenuOpen)}
                            >
                                {isMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
                            </Button>
                        </div>
                    </div>

                    {/* Mobile Navigation */}
                    {isMenuOpen && (
                        <div className="md:hidden py-4 border-t border-border">
                            <div className="flex flex-col space-y-4">
                                {navigation.map((item) => (
                                    <ScrollLink
                                        key={item.name}
                                        to={item.to}
                                        smooth={true}
                                        duration={600}
                                        offset={-70}
                                        className={
                                            item.isBrand
                                                ? "italic tracking-wide bg-gradient-to-r from-blue-500 to-purple-500 bg-clip-text text-transparent font-semibold py-2 cursor-pointer"
                                                : "text-slate-700 dark:text-slate-300 hover:text-blue-500 dark:hover:text-blue-400 transition-colors duration-200 font-medium py-2 cursor-pointer"
                                        }
                                        onClick={() => setIsMenuOpen(false)}
                                    >
                                        {item.name}
                                    </ScrollLink>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </nav>

            {/* Main Content */}
            <main className="pt-20">{children}</main>

            {/* Footer */}
            <footer className="bg-muted border-t border-border py-12">
                <div className="max-w-7xl mx-auto px-6 sm:px-8 text-center">
                    <p className="text-foreground/60 mb-4">
                        "Engineers like to solve problems. If there are no problems available, they create their own."
                    </p>
                    <p className="text-foreground/80">
                        © 2026 Abdullah Syed. Building the future, one solution at a time.
                    </p>
                </div>
            </footer>
        </div>
    );
}
